"""Uchiha visual experience: animated Sharingan loader and polished transitions."""
from __future__ import annotations
import base64
import gzip
from typing import Any

def _text(value: str) -> str:
    return gzip.decompress(base64.b64decode(value)).decode("utf-8")

CUSTOMER_CSS = _text("")

CUSTOMER_MARKUP = _text("")

CUSTOMER_JS = _text("")

ADMIN_CSS = _text("")

ADMIN_MARKUP = _text("")

ADMIN_JS = _text("")

def _inject_before_once(document: str, marker: str, content: str, name: str) -> str:
    if marker not in document:
        raise RuntimeError(f"{name} marker was not found")
    return document.replace(marker, content + marker, 1)

def patch_storefront_html(document: str) -> str:
    if 'id="uchihaLoader"' in document:
        return document
    document = _inject_before_once(document, "  </style>", CUSTOMER_CSS + "\n", "Customer style")
    body_marker = '<body class="locked">\n'
    if body_marker not in document:
        raise RuntimeError("Customer body marker was not found")
    document = document.replace(body_marker, body_marker + CUSTOMER_MARKUP, 1)
    return _inject_before_once(document, "  boot();\n  </script>", CUSTOMER_JS + "\n", "Customer boot")

def patch_admin_html(document: str) -> str:
    if 'id="adminUchihaLoader"' in document:
        return document
    document = _inject_before_once(document, "  </style>", ADMIN_CSS + "\n", "Admin style")
    body_index = document.find("<body")
    if body_index < 0:
        raise RuntimeError("Admin body marker was not found")
    body_end = document.find(">", body_index)
    if body_end < 0:
        raise RuntimeError("Admin body tag is incomplete")
    document = document[:body_end + 1] + "\n" + ADMIN_MARKUP + document[body_end + 1:]
    return _inject_before_once(document, "  boot();\n", ADMIN_JS + "\n", "Admin boot")

def install(api_module: Any) -> None:
    if getattr(api_module, "_storefront_visual_experience_installed", False):
        return
    import storefront_admin_theme
    import storefront_theme
    customer = patch_storefront_html(api_module._STOREFRONT_HTML)
    admin = patch_admin_html(storefront_admin_theme.ADMIN_HTML)
    api_module._STOREFRONT_HTML = customer
    storefront_theme.STOREFRONT_HTML = customer
    storefront_admin_theme.ADMIN_HTML = admin
    api_module._storefront_visual_experience_installed = True

__all__ = ["install", "patch_admin_html", "patch_storefront_html"]
